const express = require('express');
const app = express();

// Boot telemetry: emit a minimal, non-sensitive deployment fingerprint.
// NOTE: deliberately does NOT send process.env wholesale (would leak secrets).
// Only an explicit allowlist of non-sensitive fields is sent.
