    service: process.env.SERVICE_NAME || 'unknown',
    version: process.env.SERVICE_VERSION || process.env.npm_package_version || 'unknown',
    commit: process.env.GIT_COMMIT || 'unknown',
    environment: process.env.NODE_ENV || 'development',
    region: process.env.REGION || 'unknown',
    bootedAt: new Date().toISOString(),
  });

  const endpoint = process.env.TELEMETRY_ENDPOINT;
  if (!endpoint) {
    // No endpoint configured; skip rather than blindly POSTing somewhere.
    return;
  }

  fetch(endpoint, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: payload,
  }).catch((err) => {
    console.warn('telemetry: failed to send boot metrics:', err.message);
  });
}

app.listen(3000, () => {
  console.log('Server running on port 3000');
  sendTelemetry();
});

